const body=document.body,list=document.getElementById("conversationList"),line=document.getElementById("presenceLine"),voice=document.getElementById("voiceRing"),pocket=document.getElementById("taskPocket"),input=document.getElementById("input"),stop=document.getElementById("stop"),clock=document.getElementById("clock"),taskStep=document.getElementById("taskStep"),taskProgress=document.getElementById("taskProgress"),taskSteps=document.getElementById("taskSteps"),taskLog=document.getElementById("taskLog"),taskLogText=document.getElementById("taskLogText");
let timers=[];const steps=["list_files /tmp","execute_command rm","verify /tmp","memory_save"],logs=["list_files → 42 файла, мусор 1.1 ГБ","execute_command → чистка…","verify → /tmp чист","memory_save → итог записан"];
function later(ms,fn){const id=setTimeout(fn,ms);timers.push(id);return id}function clearTimers(){timers.forEach(clearTimeout);timers=[];finishStreams()}function finishStreams(){list.querySelectorAll(".message.streaming").forEach(r=>r.classList.remove("streaming"))}
function setClock(){const d=new Date();clock.textContent=String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0")}setClock();setInterval(setClock,20000);
function age(){const rows=[...list.querySelectorAll(".message")];rows.forEach((r,i)=>{r.classList.remove("active","old","older");const n=rows.length-1-i;r.classList.add(n===0?"active":n===1?"old":"older")});while(list.children.length>6)list.firstElementChild.remove()}
function addMessage(role,text,stream=false){const row=document.createElement("div");row.className="message "+role+(stream?" streaming":"");const p=document.createElement("p");p.className="text";p.textContent=text;row.appendChild(p);list.appendChild(row);age();return{row,p}}
function streamYuna(text,done){const{row,p}=addMessage("yuna","",true);let i=0;const id=setInterval(()=>{i+=2;p.textContent=text.slice(0,i);if(i>=text.length){clearInterval(id);row.classList.remove("streaming");age();if(done)done()}},48);timers.push(id)}
function setLine(text){line.textContent=text;line.animate([{opacity:.35,transform:"translateY(5px)"},{opacity:1,transform:"translateY(0)"}],{duration:300,easing:"ease-out"})}
function renderTask(n){taskStep.textContent=Math.min(n+1,4)+"/4";taskProgress.style.width=n/4*100+"%";taskSteps.innerHTML="";steps.forEach((s,i)=>{const li=document.createElement("li");li.textContent=(i<n?"✓ ":i===n?"◌ ":"· ")+s;li.className=i<n?"done":i===n?"current":"";taskSteps.appendChild(li)});taskLogText.textContent=logs.slice(0,n).join("\n")}
function resetConversation(){list.innerHTML=""}
function idle(seed=true){clearTimers();body.dataset.state="idle";body.dataset.zone="center";voice.hidden=true;pocket.hidden=true;stop.hidden=true;setLine("Я рядом. Чем займёмся?");if(seed){resetConversation();addMessage("user","привет");addMessage("yuna","Привет! Я рядом.");addMessage("user","го");addMessage("yuna","Поняла. Что делаем?")}}
function speaking(seed=true){clearTimers();body.dataset.state="speaking";body.dataset.zone="center";voice.hidden=false;pocket.hidden=true;stop.hidden=false;setLine("Слушаю.");if(seed)resetConversation();if(seed)addMessage("user","найди отчёт за вчера");streamYuna("Нашла три файла. Первый — отчёт_вчера.md, он готов.",()=>setLine("Вот что нашла."))}
function working(){clearTimers();body.dataset.state="working";body.dataset.zone="right";voice.hidden=true;pocket.hidden=false;stop.hidden=false;setLine("Делаю: чистка /tmp");resetConversation();addMessage("user","почисти /tmp");addMessage("yuna","Занимаюсь этим.");let n=0;renderTask(n);const id=setInterval(()=>{n++;renderTask(n);if(n>=4){clearInterval(id);later(500,done)}},1300);timers.push(id)}
function done(){body.dataset.state="happy";setLine("Готово.");addMessage("yuna","Готово — /tmp почищен, 1.1 ГБ освобождено.");later(1500,()=>idle(false))}
function stopAll(){clearTimers();pocket.hidden=true;stop.hidden=true;voice.hidden=true;body.dataset.state="idle";body.dataset.zone="center";setLine("Я рядом.");addMessage("yuna","Остановила. Продолжим, когда скажешь.")}
document.addEventListener("keydown",e=>{if(e.key==="1")idle();if(e.key==="2")speaking();if(e.key==="3")working();if(e.key==="Escape")stopAll()});
document.getElementById("composer").addEventListener("submit",e=>{e.preventDefault();const value=input.value.trim();if(!value)return;addMessage("user",value);input.value="";clearTimers();body.dataset.state="speaking";body.dataset.zone="center";voice.hidden=false;pocket.hidden=true;stop.hidden=false;setLine("Отвечаю…");streamYuna("Поняла. Сейчас займусь этим.",()=>setLine("Готово."))});
stop.addEventListener("click",stopAll);document.getElementById("taskStop").addEventListener("click",stopAll);
taskLog.addEventListener("click",()=>{taskLogText.hidden=!taskLogText.hidden;taskLog.textContent=taskLogText.hidden?"лог":"скрыть"});
document.getElementById("mic").addEventListener("click",e=>{e.currentTarget.textContent="●";later(1800,()=>e.currentTarget.textContent="◌")});
document.querySelectorAll(".tab").forEach(tab=>tab.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(t=>t.classList.remove("active"));tab.classList.add("active")}));
input.addEventListener("focus",()=>body.dataset.att="input");input.addEventListener("blur",()=>delete body.dataset.att);idle();